command:
mkdir -p outputs/station-reference-views/{windows,linux}
for preset in Windows Linux; do
  case "$preset" in
    Windows) name=windows/RVA-Night-Shift.exe ;;
    Linux) name=linux/RVA-Night-Shift.x86_64 ;;
  esac
  godot --headless --path godot/station_trial --export-release "$preset" "$PWD/outputs/station-reference-views/$name" > "outputs/station-reference-views/export-$preset.log" 2>&1 || { tail -20 "outputs/station-reference-views/export-$preset.log"; exit 1; }
  echo "PASS: Created revised $preset release."
done
outputs/station-reference-views/linux/RVA-Night-Shift.x86_64 --headless --audio-driver Dummy --quit-after 30
file outputs/station-reference-views/windows/RVA-Night-Shift.exe
